function checkEntries(){for(const side of ['mine','foe'])if(getMon(side)){const marker=ST.hazardEntry[side];if(marker?.waiting){marker.key=sideInfo(side).key;delete marker.waiting;applyHazards(side);}else if(marker?.key!==sideInfo(side).key)applyHazards(side,true);else if(marker.v!==2){const effect=entryEffects(side);if(marker.damage===true)marker.damage=Object.fromEntries((effect?.parts||[]).map(part=>[part.l,true]));marker.status=marker.status&&!!getMon(side).status;marker.web=marker.web&&effect?.spe!=null;marker.v=2;save();}}}
